-- Recorded pronunciations, generated by the admin panel when a word is saved.
--
-- native_spelling: the word in its own script, so a native voice can read it
--   (тоска, 木漏れ日). Empty means "read the word as written".
-- voice_locale: which voice reads it (e.g. 'ja-JP', 'en-US'). Empty means
--   "choose from the word's language". Set it per word for loanwords that
--   English speakers say in English (catharsis, nostalgia).
-- The recording itself is stored in the public `pronunciations` bucket and
-- its URL in words.audio_url, which the app already plays.

alter table public.words
  add column if not exists native_spelling text
    check (native_spelling is null or char_length(native_spelling) between 1 and 120),
  add column if not exists voice_locale text
    check (voice_locale is null or voice_locale ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,4})?$');

comment on column public.words.native_spelling is
  'The word in its native script for the recorded pronunciation. Null = use the word as written.';
comment on column public.words.voice_locale is
  'Voice used for the recorded pronunciation (BCP-47, e.g. ja-JP). Null = chosen from language.';

-- Public read (the app streams the files); only the service role writes.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('pronunciations', 'pronunciations', true, 1048576, array['audio/mpeg'])
on conflict (id) do nothing;
